/**
 * The generator of diagrams (ADR 0019): each diagram whose source is
 * structured and in the repository is rendered from that source into its
 * marked region of a hand-written doc, and nothing outside a region is ever
 * rewritten. A region opens with
 * `<!-- diagram:<name> generated by pnpm diagrams:generate, never edit by hand -->`
 * and closes with `<!-- /diagram:<name> -->`; to place a new one, write the
 * two lines `<!-- diagram:<name> -->` and `<!-- /diagram:<name> -->` where
 * it belongs and run the generator.
 *
 * The core knows no diagram: each is a module implementing `Diagram`, listed
 * in `diagram-list.ts`.
 */
import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { gitIn } from "./git.js";
import { byCodePoint } from "./order.js";

/** The command that writes the regions, which every failure names. */
export const GENERATE_COMMAND = "pnpm diagrams:generate";

/** The module listing the diagrams the generator knows. */
export const DIAGRAM_LIST = "release/src/diagram-list.ts";

/** A generated diagram: one module per diagram, listed in `diagram-list.ts`. */
export interface Diagram {
  /** Its name, kebab-case: the region's and the block's `%% diagram:`. */
  readonly name: string;
  /** The `/`-separated path, from the root, of the doc holding its region. */
  readonly document: string;
  /**
   * The Markdown of its region, read from the repository at `root`: the
   * `mermaid` block declaring `%% diagram: <name>` (`mermaidBlock` writes
   * it), then whatever the diagram adds under it (a table), ending with a
   * newline. Throws when its sources cannot be read.
   */
  render(root: string): Promise<string>;
}

/** The regions the generator writes in one document, by diagram name. */
export interface GeneratedDocument {
  document: string;
  /** Each region's whole text, from its opening line to its closing one. */
  regions: { name: string; text: string }[];
}

export type ProblemKind = "changed" | "missing" | "unknown" | "malformed";

export interface Problem {
  kind: ProblemKind;
  /** One line naming the document, and `pnpm diagrams:generate`. */
  message: string;
}

export interface Comparison {
  /** Each document whose regions differ, by path, with its regions rewritten. */
  files: Map<string, string>;
  /** In code-point order of the document, then by line. */
  problems: Problem[];
  /** How many regions the generator writes. */
  regions: number;
}

const NAME = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const OPEN = /^<!--\s*diagram:([^\s>]+)(?:\s.*)?-->\s*$/;
const CLOSE = /^<!--\s*\/diagram:([^\s>]+)\s*-->\s*$/;
const FENCE = /^ {0,3}(`{3,}|~{3,})/;

const openLine = (name: string) =>
  `<!-- diagram:${name} generated by ${GENERATE_COMMAND}, never edit by hand -->`;
const closeLine = (name: string) => `<!-- /diagram:${name} -->`;

/**
 * Renders each of `diagrams` from the repository at `root` into the text of
 * its region, grouped by document; documents and regions in code-point
 * order. Throws on two diagrams of one name, a name not kebab-case, or a
 * block that does not declare its name.
 */
export async function generateDiagrams(
  root: string,
  diagrams: readonly Diagram[],
): Promise<GeneratedDocument[]> {
  const names = new Set<string>();
  const byDocument = new Map<string, { name: string; text: string }[]>();
  for (const diagram of [...diagrams].sort((a, b) =>
    byCodePoint(a.name, b.name),
  )) {
    const { name, document } = diagram;
    if (!NAME.test(name)) {
      throw new Error(`The diagram name ${name} is not kebab-case.`);
    }
    if (names.has(name)) throw new Error(`Two diagrams are named ${name}.`);
    names.add(name);
    const markdown = await diagram.render(root);
    if (!new RegExp(`^\\s*%% diagram: ${name}$`, "m").test(markdown)) {
      throw new Error(
        `The diagram ${name} renders no \`%% diagram: ${name}\` line in its block.`,
      );
    }
    const text = `${openLine(name)}\n\n${markdown.replace(/\n*$/, "\n")}\n${closeLine(name)}`;
    byDocument.set(document, [
      ...(byDocument.get(document) ?? []),
      { name, text },
    ]);
  }
  return [...byDocument]
    .sort(([a], [b]) => byCodePoint(a, b))
    .map(([document, regions]) => ({ document, regions }));
}

/** A problem at a 0-based line of its document. */
interface LineProblem {
  line: number;
  problem: Problem;
}

interface Region {
  name: string;
  /** The 0-based indexes of its opening and closing lines. */
  open: number;
  close: number;
}

/**
 * The regions of a document's `lines`, and the problems of its markers.
 * Marker lines inside fenced code are text, not markers.
 */
function readRegions(
  document: string,
  lines: readonly string[],
): { regions: Region[]; seen: Set<string>; problems: LineProblem[] } {
  const regions: Region[] = [];
  const seen = new Set<string>();
  const problems: LineProblem[] = [];
  const malformed = (line: number, what: string, fix: string) =>
    problems.push({
      line,
      problem: {
        kind: "malformed",
        message: `${document}:${String(line + 1)}: ${what}. ${fix}, then run \`${GENERATE_COMMAND}\`.`,
      },
    });
  let fence: string | null = null;
  let opened: { name: string; open: number } | null = null;

  for (const [index, line] of lines.entries()) {
    const marker = FENCE.exec(line)?.[1];
    if (fence !== null) {
      if (marker?.[0] === fence[0] && marker.length >= fence.length) {
        if (line.trim() === marker) fence = null;
      }
      continue;
    }
    if (marker !== undefined) {
      fence = marker;
      continue;
    }
    const opening = OPEN.exec(line)?.[1];
    const closing = CLOSE.exec(line)?.[1];
    if (opened !== null && (opening !== undefined || closing !== undefined)) {
      const current = opened;
      opened = null;
      if (closing === current.name) {
        regions.push({ name: current.name, open: current.open, close: index });
        continue;
      }
      malformed(
        current.open,
        `the region of the diagram ${current.name} is not closed by \`${closeLine(current.name)}\` before line ${String(index + 1)}`,
        "Fix its markers",
      );
      if (closing !== undefined) continue;
    }
    if (opening !== undefined) {
      if (seen.has(opening)) {
        malformed(
          index,
          `a second region of the diagram ${opening}`,
          "Remove one",
        );
      }
      seen.add(opening);
      opened = { name: opening, open: index };
    } else if (closing !== undefined) {
      malformed(
        index,
        `\`${closeLine(closing)}\` closes no region`,
        "Fix its markers",
      );
    }
  }
  if (opened !== null) {
    const { name, open } = opened;
    malformed(
      open,
      `the region of the diagram ${name} is not closed by \`${closeLine(name)}\``,
      "Fix its markers",
    );
  }
  return { regions, seen, problems };
}

/** The skills CLI's lock, from the root: it names the Upstream skills. */
const SKILLS_LOCK = "skills-lock.json";

/**
 * The names of the Upstream skills, the keys of the lock's `skills`; none
 * when the repository has no lock.
 */
async function upstreamSkills(root: string): Promise<Set<string>> {
  const text = await readFile(join(root, SKILLS_LOCK), "utf8").catch(
    () => undefined,
  );
  if (text === undefined) return new Set();
  const { skills } = JSON.parse(text) as { skills?: Record<string, unknown> };
  return new Set(Object.keys(skills ?? {}));
}

/**
 * The Markdown files git tracks or would track, `/`-separated, but those of
 * the Upstream skills' folders of `.claude/skills/`: their Markdown is
 * upstream's text, never the repository's.
 */
async function markdownFiles(root: string): Promise<string[]> {
  const listed = await gitIn(root)([
    "ls-files",
    "-z",
    "--cached",
    "--others",
    "--exclude-standard",
    "--",
    "*.md",
  ]);
  const upstream = await upstreamSkills(root);
  return listed
    .split("\0")
    .filter(
      (path) =>
        path !== "" &&
        !upstream.has(/^\.claude\/skills\/([^/]+)\//.exec(path)?.[1] ?? ""),
    );
}

/**
 * Compares the regions of the repository at `root` with what `diagrams`
 * render. It reads every Markdown file git tracks or would track (so not
 * an ignored copy of a doc), and the documents of `diagrams`. A region is
 * known when its document is the one of its diagram.
 */
export async function compareDiagrams(
  root: string,
  diagrams: readonly Diagram[],
): Promise<Comparison> {
  const generated = await generateDiagrams(root, diagrams);
  const expected = new Map(
    generated.map(({ document, regions }) => [
      document,
      new Map(regions.map(({ name, text }) => [name, text])),
    ]),
  );
  const homes = new Map(diagrams.map(({ name, document }) => [name, document]));
  const documents = [
    ...new Set([...(await markdownFiles(root)), ...expected.keys()]),
  ].sort(byCodePoint);

  const files = new Map<string, string>();
  const problems: Problem[] = [];
  for (const document of documents) {
    const text = await readFile(join(root, document), "utf8").catch(() => "");
    const lines = text.split("\n");
    const found = readRegions(document, lines);
    const wanted = expected.get(document) ?? new Map<string, string>();
    const known = found.regions.filter(({ name }) => wanted.has(name));
    const regionProblems = [...found.problems];

    for (const { name, open } of found.regions) {
      if (wanted.has(name)) continue;
      const home = homes.get(name);
      regionProblems.push({
        line: open,
        problem: {
          kind: "unknown",
          message:
            home === undefined
              ? `${document}: a region of the diagram ${name}, which no diagram of \`${GENERATE_COMMAND}\` writes. Remove it, or add the diagram to ${DIAGRAM_LIST}.`
              : `${document}: a region of the diagram ${name}, which \`${GENERATE_COMMAND}\` writes in ${home} only. Remove it, or move it there.`,
        },
      });
    }

    const rewritten = [...lines];
    for (const { name, open, close } of [...known].reverse()) {
      const want = wanted.get(name) ?? "";
      if (lines.slice(open, close + 1).join("\n") === want) continue;
      rewritten.splice(open, close - open + 1, ...want.split("\n"));
      regionProblems.push({
        line: open,
        problem: {
          kind: "changed",
          message: `${document}: the region of the diagram ${name} differs from what \`${GENERATE_COMMAND}\` writes.`,
        },
      });
    }
    if (rewritten.join("\n") !== text)
      files.set(document, rewritten.join("\n"));

    problems.push(
      ...regionProblems
        .sort((a, b) => a.line - b.line)
        .map(({ problem }) => problem),
    );
    for (const name of wanted.keys()) {
      if (found.seen.has(name)) continue;
      problems.push({
        kind: "missing",
        message: `${document}: no region for the diagram ${name}. Add the lines \`<!-- diagram:${name} -->\` and \`${closeLine(name)}\` where it belongs, then run \`${GENERATE_COMMAND}\`.`,
      });
    }
  }
  return {
    files,
    problems,
    regions: generated.reduce((sum, { regions }) => sum + regions.length, 0),
  };
}
